        username: playerData?.username && playerData.username.trim() !== "" ? playerData.username : playerData?.email && playerData.email.trim() !== "" ? playerData.email.split("@")[0] : playerData?.phone ? "user_" + playerData.phone : "guest_" + Date.now(),
